package android.hardware.input; import java.util.*; import android.os.Handler; public class InputManager { public interface InputDeviceListener { void onInputDeviceAdded(int i);void onInputDeviceRemoved(int i);void onInputDeviceChanged(int i); } public static final InputManager INSTANCE=new InputManager(); public final List<InputDeviceListener> listeners=new ArrayList<>(); public void registerInputDeviceListener(InputDeviceListener l,Handler h){listeners.add(l);} public void removed(int i){for(InputDeviceListener l:listeners)l.onInputDeviceRemoved(i);} }
